SELECT bu_id, bu_name, bu_code, book_id, book_name, org_id, org_name, period, revenue, cost, profit, currency, status, create_by, create_time, update_by, update_time FROM finance_bu_data
AND bu_name LIKE '%' || #{params.buName} || '%'
AND bu_code = #{params.buCode}
AND book_id = #{params.bookId}
AND org_id = #{params.orgId}
AND period = #{params.period}
AND status = #{params.status}
ORDER BY create_time DESC

SELECT bu_id, bu_name, bu_code, book_id, book_name, org_id, org_name, period, revenue, cost, profit, currency, status, create_time FROM finance_bu_data
AND book_id = #{params.bookId}
AND org_id = #{params.orgId}
AND period = #{params.period}
ORDER BY create_time DESC
